package com.simibubi.create.test;

import com.simibubi.create.*;
import com.simibubi.create.api.behaviour.movement.MovementBehaviour;
import com.simibubi.create.api.contraption.BlockMovementChecks;
import com.simibubi.create.content.contraptions.*;
import com.simibubi.create.content.contraptions.actors.*;
import com.simibubi.create.content.contraptions.actors.harvester.*;
import com.simibubi.create.content.contraptions.actors.plough.*;
import com.simibubi.create.content.contraptions.bearing.*;
import com.simibubi.create.content.contraptions.behaviour.MovementContext;
import com.simibubi.create.content.contraptions.glue.SuperGlueEntity;
import java.util.*;
import net.fabricmc.fabric.api.gametest.v1.GameTest;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.world.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.item.*;
import net.minecraft.world.item.context.UseOnContext;
import net.minecraft.world.level.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.state.*;
import net.minecraft.world.level.block.state.properties.*;
import net.minecraft.world.phys.*;

public class FarmingActorGameTests {
    private static final BlockPos P=new BlockPos(3,5,4),TOOL=P.north(),B=P.below();
    private static ControlledContraptionEntity moving(GameTestHelper h,boolean plough)throws Exception{
        h.setBlock(P,Blocks.STONE);h.setBlock(P.east(),Blocks.BARREL);h.setBlock(TOOL,(plough?AllBlocks.MECHANICAL_PLOUGH:AllBlocks.MECHANICAL_HARVESTER).defaultBlockState().setValue(AttachedActorBlock.FACING,Direction.NORTH));
        h.getLevel().addFreshEntity(new SuperGlueEntity(h.getLevel(),SuperGlueEntity.span(h.absolutePos(TOOL),h.absolutePos(P.east()))));var structure=new BearingContraption(false,Direction.UP);structure.assemble(h.getLevel(),h.absolutePos(B));structure.tryRemoveBlocksFromWorld(h.getLevel(),BlockPos.ZERO);var owner=new ControlledContraptionEntity(AllEntityTypes.CONTROLLED_CONTRAPTION,h.getLevel());owner.setContraption(structure);owner.setPos(Vec3.atLowerCornerOf(h.absolutePos(P)));owner.tickActors();var ctx=ctx(owner);ctx.motion=ctx.relativeMotion=new Vec3(0,0,-.2);return owner;
    }
    private static MovementContext ctx(ControlledContraptionEntity owner){return owner.getContraption().getActorAt(new BlockPos(0,0,-1)).right;}
    private static HarvesterMovementBehaviour harvester(){return (HarvesterMovementBehaviour)MovementBehaviour.REGISTRY.get(AllBlocks.MECHANICAL_HARVESTER);}
    private static PloughMovementBehaviour plough(){return (PloughMovementBehaviour)MovementBehaviour.REGISTRY.get(AllBlocks.MECHANICAL_PLOUGH);}
    private static long count(ControlledContraptionEntity owner,Item item){long count=0;for(var view:owner.getContraption().getStorage().getAllItems())if(view.getResource().isOf(item))count+=view.getAmount();return count;}
    private static void farm(GameTestHelper h,BlockState crop){h.setBlock(TOOL.below(),Blocks.FARMLAND.defaultBlockState().setValue(FarmlandBlock.MOISTURE,7));h.setBlock(TOOL,crop);}
    private static void harvest(GameTestHelper h,ControlledContraptionEntity owner){harvester().visitNewPosition(ctx(owner),h.absolutePos(TOOL));}
    private static void clear(GameTestHelper h,ControlledContraptionEntity owner){plough().visitNewPosition(ctx(owner),h.absolutePos(TOOL));for(int i=0;i<150&&ctx(owner).stall;i++)plough().tick(ctx(owner));}
    @GameTest public void matureVanillaWheatIsCollectedAndReplantedAtAgeZero(GameTestHelper h)throws Exception{var owner=moving(h,false);farm(h,Blocks.WHEAT.defaultBlockState().setValue(CropBlock.AGE,7));harvest(h,owner);h.assertBlockPresent(Blocks.WHEAT,TOOL);h.assertValueEqual(h.getBlockState(TOOL).getValue(CropBlock.AGE),0,"Replanted wheat");h.assertValueEqual(count(owner,Items.WHEAT),1L,"One harvest");h.succeed();}
    @GameTest public void replantSubtractsExactlyOneSeedAndKeepsCustomCropState(GameTestHelper h)throws Exception{var owner=moving(h,false);farm(h,FarmingActorTestFixtures.CROP.defaultBlockState().setValue(BlockStateProperties.AGE_3,3).setValue(BlockStateProperties.PERSISTENT,true));harvest(h,owner);h.assertValueEqual(count(owner,FarmingActorTestFixtures.CROP.asItem()),2L,"One of three planting items withheld");h.assertValueEqual(count(owner,Items.WHEAT),2L,"Other produce retained");h.assertTrue(h.getBlockState(TOOL).getValue(BlockStateProperties.AGE_3)==0&&h.getBlockState(TOOL).getValue(BlockStateProperties.PERSISTENT),"Custom age property and independent flag survive");h.succeed();}
    @GameTest public void immatureCropIsSkippedByTheSourceDefault(GameTestHelper h)throws Exception{var owner=moving(h,false);var state=FarmingActorTestFixtures.CROP.defaultBlockState().setValue(BlockStateProperties.AGE_3,1);farm(h,state);harvest(h,owner);h.assertTrue(h.getBlockState(TOOL)==state&&count(owner,Items.WHEAT)==0,"Immature crop untouched");h.succeed();}
    @GameTest public void partiallyGrownSettingHarvestsAndReplantsIntermediateAge(GameTestHelper h)throws Exception{var owner=moving(h,false);farm(h,FarmingActorTestFixtures.CROP.defaultBlockState().setValue(BlockStateProperties.AGE_3,1));boolean old=ContraptionSettings.harvestPartiallyGrown;try{ContraptionSettings.harvestPartiallyGrown=true;harvest(h,owner);}finally{ContraptionSettings.harvestPartiallyGrown=old;}h.assertValueEqual(h.getBlockState(TOOL).getValue(BlockStateProperties.AGE_3),0,"Partial crop reset");h.assertValueEqual(count(owner,FarmingActorTestFixtures.CROP.asItem()),2L,"Partial harvest holds seed");h.succeed();}
    @GameTest public void noReplantKeepsAllSeedsAndRemovesTheCrop(GameTestHelper h)throws Exception{var owner=moving(h,false);farm(h,FarmingActorTestFixtures.CROP.defaultBlockState().setValue(BlockStateProperties.AGE_3,3));boolean old=ContraptionSettings.harvesterReplants;try{ContraptionSettings.harvesterReplants=false;harvest(h,owner);}finally{ContraptionSettings.harvesterReplants=old;}h.assertBlockPresent(Blocks.AIR,TOOL);h.assertValueEqual(count(owner,FarmingActorTestFixtures.CROP.asItem()),3L,"No seed withheld");h.succeed();}
    @GameTest public void newlyPlantedCropIsSkippedUnlessPartialHarvestAndNoReplantAreBothEnabled(GameTestHelper h)throws Exception{var owner=moving(h,false);farm(h,FarmingActorTestFixtures.CROP.defaultBlockState());boolean partial=ContraptionSettings.harvestPartiallyGrown,replant=ContraptionSettings.harvesterReplants;try{ContraptionSettings.harvestPartiallyGrown=true;harvest(h,owner);h.assertBlockPresent(FarmingActorTestFixtures.CROP,TOOL);ContraptionSettings.harvesterReplants=false;harvest(h,owner);}finally{ContraptionSettings.harvestPartiallyGrown=partial;ContraptionSettings.harvesterReplants=replant;}h.assertBlockPresent(Blocks.AIR,TOOL);h.succeed();}
    @GameTest public void nonHarvestableTagWinsOverAValidMatureCrop(GameTestHelper h)throws Exception{var owner=moving(h,false);var crop=FarmingActorTestFixtures.PROTECTED_CROP.defaultBlockState().setValue(BlockStateProperties.AGE_3,3);farm(h,crop);harvest(h,owner);h.assertTrue(h.getBlockState(TOOL)==crop&&count(owner,Items.WHEAT)==0,"Tag vetoes harvest");h.succeed();}
    @GameTest public void carrotsAndPotatoesUseTheirOwnPlantingItems(GameTestHelper h)throws Exception{var owner=moving(h,false);for(var pair:List.of(Map.entry(Blocks.CARROTS,Items.CARROT),Map.entry(Blocks.POTATOES,Items.POTATO))){farm(h,pair.getKey().defaultBlockState().setValue(CropBlock.AGE,7));harvest(h,owner);h.assertTrue(h.getBlockState(TOOL).is(pair.getKey())&&h.getBlockState(TOOL).getValue(CropBlock.AGE)==0,"Vanilla root crop reset");}h.succeed();}
    @GameTest public void sweetBerryBushReturnsToAgeOneAndYoungBushIsUntouched(GameTestHelper h)throws Exception{var owner=moving(h,false);h.setBlock(TOOL.below(),Blocks.DIRT);h.setBlock(TOOL,Blocks.SWEET_BERRY_BUSH.defaultBlockState().setValue(SweetBerryBushBlock.AGE,3));harvest(h,owner);h.assertValueEqual(h.getBlockState(TOOL).getValue(SweetBerryBushBlock.AGE),1,"Berry base retained");long berries=count(owner,Items.SWEET_BERRIES);harvest(h,owner);h.assertValueEqual(count(owner,Items.SWEET_BERRIES),berries,"Young bush skipped");h.succeed();}
    @GameTest public void matureCocoaRetainsFacingAndResetsItsAge(GameTestHelper h)throws Exception{var owner=moving(h,false);h.setBlock(TOOL.west(),Blocks.JUNGLE_LOG);h.setBlock(TOOL.east(),Blocks.JUNGLE_LOG);h.setBlock(TOOL,Blocks.COCOA.defaultBlockState().setValue(CocoaBlock.FACING,Direction.WEST).setValue(CocoaBlock.AGE,2));harvest(h,owner);h.assertBlockPresent(Blocks.COCOA,TOOL);h.assertTrue(h.getBlockState(TOOL).getValue(CocoaBlock.FACING)==Direction.WEST&&h.getBlockState(TOOL).getValue(CocoaBlock.AGE)==0,"Cocoa state retained");h.assertValueEqual(count(owner,Items.COCOA_BEANS),2L,"One bean held for replant");h.succeed();}
    @GameTest public void leavesUseRealShearsLootRatherThanSaplingRandomness(GameTestHelper h)throws Exception{var owner=moving(h,false);h.setBlock(TOOL,Blocks.OAK_LEAVES);harvest(h,owner);h.assertBlockPresent(Blocks.AIR,TOOL);h.assertValueEqual(count(owner,Items.OAK_LEAVES),1L,"Sheared leaf block");h.succeed();}
    @GameTest public void upperSugarCaneIsCutWithoutRemovingItsRoot(GameTestHelper h)throws Exception{var owner=moving(h,false);h.setBlock(TOOL.below(2),Blocks.DIRT);h.setBlock(TOOL.below(2).east(),Blocks.WATER);h.setBlock(TOOL.below(),Blocks.SUGAR_CANE);h.setBlock(TOOL,Blocks.SUGAR_CANE);harvest(h,owner);h.assertBlockPresent(Blocks.SUGAR_CANE,TOOL.below());h.assertBlockPresent(Blocks.AIR,TOOL);h.assertValueEqual(count(owner,Items.SUGAR_CANE),1L,"Cut section collected");h.succeed();}
    @GameTest public void underwaterKelpCutRestoresWaterInTheHarvestedCell(GameTestHelper h)throws Exception{var owner=moving(h,false);h.setBlock(TOOL.below(),Blocks.STONE);h.setBlock(TOOL,Blocks.KELP);harvest(h,owner);h.assertBlockPresent(Blocks.WATER,TOOL);h.assertTrue(count(owner,Items.KELP)>0,"Kelp collected");h.succeed();}
    @GameTest public void flowersAreCutButFireAndSolidStoneAreNotHarvested(GameTestHelper h)throws Exception{var owner=moving(h,false);h.setBlock(TOOL.below(),Blocks.DIRT);h.setBlock(TOOL,Blocks.DANDELION);harvest(h,owner);h.assertValueEqual(count(owner,Items.DANDELION),1L,"Flower cut");h.setBlock(TOOL,Blocks.STONE);harvest(h,owner);h.assertBlockPresent(Blocks.STONE,TOOL);h.setBlock(TOOL,Blocks.FIRE);harvest(h,owner);h.assertBlockPresent(Blocks.FIRE,TOOL);h.succeed();}
    @GameTest public void fabricCustomPlantCheckCanRecognizeNonVegetationPlants(GameTestHelper h)throws Exception{var owner=moving(h,false);h.setBlock(TOOL,FarmingActorTestFixtures.SPECIAL.defaultBlockState().setValue(BlockStateProperties.POWERED,false));harvest(h,owner);h.assertBlockPresent(FarmingActorTestFixtures.SPECIAL,TOOL);h.setBlock(TOOL,FarmingActorTestFixtures.SPECIAL.defaultBlockState().setValue(BlockStateProperties.POWERED,true));harvest(h,owner);h.assertBlockPresent(Blocks.AIR,TOOL);h.assertValueEqual(count(owner,Items.DIAMOND),1L,"Extension crop harvested");h.succeed();}
    @GameTest public void fullMountedInventoryDropsOnlyTheUninsertedHarvest(GameTestHelper h)throws Exception{var owner=moving(h,false);var inventory=owner.getContraption().getStorage().getAllItemStorages().get(new BlockPos(1,0,0));for(int i=0;i<inventory.getSlotCount();i++)inventory.setStackInSlot(i,new ItemStack(Items.STONE,64));farm(h,FarmingActorTestFixtures.CROP.defaultBlockState().setValue(BlockStateProperties.AGE_3,3));harvest(h,owner);var drops=h.getLevel().getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,owner.getBoundingBox().inflate(3));h.assertValueEqual(drops.stream().filter(item->item.getItem().is(Items.WHEAT)).mapToInt(item->item.getItem().getCount()).sum(),2,"Produce drops once");h.assertValueEqual(drops.stream().filter(item->item.getItem().is(FarmingActorTestFixtures.CROP.asItem())).mapToInt(item->item.getItem().getCount()).sum(),2,"Reserved planting item not dropped");h.succeed();}
    @GameTest public void backwardsAndDisabledActorsObeySourceActivationRules(GameTestHelper h)throws Exception{var owner=moving(h,false);var context=ctx(owner);context.relativeMotion=new Vec3(0,0,1);h.assertFalse(harvester().isActive(context),"Backward harvesting disabled");context.relativeMotion=new Vec3(1,0,.1);h.assertTrue(harvester().isActive(context),"Perpendicular tolerance");context.disabled=true;h.assertFalse(harvester().isActive(context),"Controls disable harvesting");h.succeed();}
    @GameTest public void attachedActorDeclaresItsRearSupportAndDoesNotPushWithItsFront(GameTestHelper h){var state=AllBlocks.MECHANICAL_HARVESTER.defaultBlockState().setValue(AttachedActorBlock.FACING,Direction.WEST);h.assertTrue(BlockMovementChecks.isBlockAttachedTowards(state,h.getLevel(),h.absolutePos(TOOL),Direction.EAST),"Rear attachment");h.assertTrue(BlockMovementChecks.isNotSupportive(state,Direction.WEST),"Front excluded from push/stick support");h.assertFalse(BlockMovementChecks.isNotSupportive(state,Direction.EAST),"Back supports structure");h.succeed();}
    @GameTest public void rootBlockCollectsItsAttachedHarvesterWithoutGlue(GameTestHelper h)throws Exception{h.setBlock(P,Blocks.STONE);h.setBlock(TOOL,AllBlocks.MECHANICAL_HARVESTER.defaultBlockState().setValue(AttachedActorBlock.FACING,Direction.NORTH));var structure=new BearingContraption(false,Direction.UP);structure.assemble(h.getLevel(),h.absolutePos(B));h.assertValueEqual(structure.getBlocks().size(),2,"Source attached-block traversal");h.succeed();}
    @GameTest public void actorWaterloggingAndRearShapeFollowAllFourHorizontalDirections(GameTestHelper h){for(var block:List.of(AllBlocks.MECHANICAL_HARVESTER,AllBlocks.MECHANICAL_PLOUGH))for(var direction:Direction.Plane.HORIZONTAL){var state=block.defaultBlockState().setValue(AttachedActorBlock.FACING,direction).setValue(AttachedActorBlock.WATERLOGGED,true);h.assertTrue(state.getFluidState().isSource(),"Waterlogged source");var box=state.getShape(h.getLevel(),h.absolutePos(TOOL)).bounds();var center=box.getCenter().subtract(.5,.5,.5);h.assertTrue(center.dot(direction.getUnitVec3())<-.3,"Shape stays at rear");}h.succeed();}
    @GameTest public void wrenchDoesNotRotateActorAndShiftRemovalReturnsOneItem(GameTestHelper h){h.setBlock(P,Blocks.STONE);h.setBlock(TOOL,AllBlocks.MECHANICAL_PLOUGH.defaultBlockState().setValue(AttachedActorBlock.FACING,Direction.NORTH));var player=h.makeMockPlayer(GameType.SURVIVAL);player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(AllItems.WRENCH));var hit=new BlockHitResult(Vec3.atCenterOf(h.absolutePos(TOOL)),Direction.NORTH,h.absolutePos(TOOL),false);var use=new UseOnContext(player,InteractionHand.MAIN_HAND,hit);h.assertValueEqual(AllItems.WRENCH.useOn(use),InteractionResult.FAIL,"Ordinary wrench fails");h.assertValueEqual(h.getBlockState(TOOL).getValue(AttachedActorBlock.FACING),Direction.NORTH,"Orientation unchanged");player.setShiftKeyDown(true);AllItems.WRENCH.useOn(use);h.assertBlockPresent(Blocks.AIR,TOOL);int returned=0;for(int i=0;i<player.getInventory().getContainerSize();i++)if(player.getInventory().getItem(i).is(AllBlocks.MECHANICAL_PLOUGH.asItem()))returned+=player.getInventory().getItem(i).getCount();h.assertValueEqual(returned,1,"Shift removal refunds exactly one actor");h.succeed();}
    @GameTest public void ploughTillsDirtAndGrassBelowItsActualWorkCell(GameTestHelper h)throws Exception{var owner=moving(h,true);for(var soil:List.of(Blocks.DIRT,Blocks.GRASS_BLOCK)){h.setBlock(TOOL.below(),soil);clear(h,owner);h.assertBlockPresent(Blocks.FARMLAND,TOOL.below());}h.succeed();}
    @GameTest public void ploughSkipsGrowingPlantsOnFarmland(GameTestHelper h)throws Exception{var owner=moving(h,true);farm(h,Blocks.WHEAT.defaultBlockState().setValue(CropBlock.AGE,7));clear(h,owner);h.assertBlockPresent(Blocks.WHEAT,TOOL);h.assertValueEqual(count(owner,Items.WHEAT),0L,"Farm crop protected");h.succeed();}
    @GameTest public void ploughBreaksFlowersAndCollectsThem(GameTestHelper h)throws Exception{var owner=moving(h,true);h.setBlock(TOOL.below(),Blocks.STONE);h.setBlock(TOOL,Blocks.DANDELION);clear(h,owner);h.assertBlockPresent(Blocks.AIR,TOOL);h.assertValueEqual(count(owner,Items.DANDELION),1L,"Cleared plant collected");h.succeed();}
    @GameTest public void snowWhitelistUsesShovelLootExactlyOnce(GameTestHelper h)throws Exception{var owner=moving(h,true);h.setBlock(TOOL.below(),Blocks.STONE);h.setBlock(TOOL,Blocks.SNOW.defaultBlockState().setValue(SnowLayerBlock.LAYERS,3));clear(h,owner);h.assertBlockPresent(Blocks.AIR,TOOL);h.assertValueEqual(count(owner,Items.SNOWBALL),3L,"Three layers produce three snowballs");h.succeed();}
    @GameTest public void ploughSkipsSolidBlocksLiquidsAndBlacklistedPortals(GameTestHelper h)throws Exception{var owner=moving(h,true);for(var block:List.of(Blocks.STONE,Blocks.WATER,Blocks.BUBBLE_COLUMN,Blocks.NETHER_PORTAL)){h.setBlock(TOOL,block);h.assertFalse(plough().canBreak(h.getLevel(),h.absolutePos(TOOL),h.getBlockState(TOOL)),"Not ploughable: "+block);}h.succeed();}
    @GameTest public void ploughThrowsAnimalsButDoesNotDamageThemOrTouchItems(GameTestHelper h)throws Exception{var owner=moving(h,true);var context=ctx(owner);context.motion=context.relativeMotion=new Vec3(1,0,0);var pig=h.spawnWithNoFreeWill(EntityTypes.PIG,TOOL);pig.setNoGravity(true);var item=new net.minecraft.world.entity.item.ItemEntity(h.getLevel(),pig.getX(),pig.getY(),pig.getZ(),new ItemStack(Items.DIAMOND));h.getLevel().addFreshEntity(item);var initialMotion=item.getDeltaMovement();plough().damageEntities(context,h.absolutePos(TOOL),h.getLevel());h.assertTrue(pig.getHealth()==pig.getMaxHealth()&&pig.getDeltaMovement().x>0,"Throw without direct damage");h.assertTrue(item.getDeltaMovement().equals(initialMotion)&&item.getItem().getCount()==1,"Item ignored");h.succeed();}
    @GameTest public void stoppingPloughDiscardsItsTransientHoePlayer(GameTestHelper h)throws Exception{var owner=moving(h,true);h.setBlock(TOOL.below(),Blocks.DIRT);clear(h,owner);var fake=(PloughBlock.PloughFakePlayer)ctx(owner).temporaryData;owner.getContraption().stop(h.getLevel());h.assertTrue(fake.isRemoved(),"Transient fake cleaned up");h.succeed();}
    @GameTest public void unloadedHarvestAndPloughQueriesDoNotCreateChunkLoads(GameTestHelper h)throws Exception{var harvester=moving(h,false);var far=new BlockPos(2000000,40,2000000);harvester().visitNewPosition(ctx(harvester),far);h.assertTrue(h.getLevel().getChunkSource().getChunkNow(far.getX()>>4,far.getZ()>>4)==null,"No harvester target load");h.assertFalse(plough().canBreak(h.getLevel(),far,Blocks.DANDELION.defaultBlockState()),"Unknown plough target skipped");h.assertTrue(h.getLevel().getChunkSource().getChunkNow(far.getX()>>4,far.getZ()>>4)==null,"No plough target load");h.succeed();}
    private static void machine(GameTestHelper h,boolean plough){h.setBlock(P,Blocks.STONE);h.setBlock(P.east(),Blocks.BARREL);h.setBlock(TOOL,(plough?AllBlocks.MECHANICAL_PLOUGH:AllBlocks.MECHANICAL_HARVESTER).defaultBlockState().setValue(AttachedActorBlock.FACING,Direction.NORTH));h.getLevel().addFreshEntity(new SuperGlueEntity(h.getLevel(),SuperGlueEntity.span(h.absolutePos(TOOL),h.absolutePos(P.east()))));h.setBlock(B,AllBlocks.MECHANICAL_BEARING.defaultBlockState().setValue(BearingBlock.FACING,Direction.UP));h.setBlock(B.below(),AllBlocks.CREATIVE_MOTOR.defaultBlockState().setValue(com.simibubi.create.content.kinetics.motor.CreativeMotorBlock.FACING,Direction.UP));}
    @GameTest(maxTicks=75) public void actualBearingHarvesterCollectsAndReplantsAWorldCrop(GameTestHelper h){h.setBlock(P.west().below(),Blocks.FARMLAND);h.setBlock(P.west(),FarmingActorTestFixtures.CROP.defaultBlockState().setValue(BlockStateProperties.AGE_3,3));machine(h,false);h.runAfterDelay(50,()->{var owner=h.getBlockEntity(B,MechanicalBearingBlockEntity.class).getMovedContraption();h.assertTrue(owner!=null,"Real assembly");h.assertValueEqual(h.getBlockState(P.west()).getValue(BlockStateProperties.AGE_3),0,"Real moving harvest reset");h.assertValueEqual(count(owner,Items.WHEAT),2L,"Actual crop output collected");h.succeed();});}
    @GameTest(maxTicks=75) public void actualBearingPloughTillsWorldSoilAsItMovesPast(GameTestHelper h){
        var soil=P.west().below();h.setBlock(soil,Blocks.GRASS_BLOCK);
        // Native zero-moisture farmland can randomly dry back to dirt before tick 50.
        // Keep a real water source in range while the actual kinetic plough crosses this cell.
        h.setBlock(soil.south(3),Blocks.WATER);machine(h,true);
        h.runAfterDelay(50,()->{h.assertBlockPresent(Blocks.FARMLAND,soil);h.succeed();});
    }
}
